<script setup lang="ts">
definePageMeta({ layout: 'admin' })
const { data, pending, error, refresh } = await useFetch<any>('/api/admin/stock', { server: false, retry: false })
const toast = useToast()
const modalOpen = ref(false)
const saving = ref(false)
const formError = ref('')
const filter = ref('all')
const form = reactive({ productId: 1, direction: 'in', quantity: 1, note: '' })
const products = computed(() => data.value?.products || [])
const visibleProducts = computed(() => {
  const rows = products.value
  if (filter.value === 'low') return rows.filter((item: any) => item.status === 'active' && item.stock <= item.lowStock)
  if (filter.value === 'healthy') return rows.filter((item: any) => item.status === 'active' && item.stock > item.lowStock)
  return rows
})
const lowCount = computed(() => products.value.filter((item: any) => item.status === 'active' && item.stock <= item.lowStock).length)
function openAdjustment(product?: any) { formError.value = ''; form.productId = Number(product?.id || products.value[0]?.id || 1); form.direction = 'in'; form.quantity = 1; form.note = ''; modalOpen.value = true }
async function saveAdjustment() {
  saving.value = true; formError.value = ''
  try {
    await $fetch('/api/admin/stock', { method: 'POST', body: { productId: form.productId, delta: (form.direction === 'in' ? 1 : -1) * Number(form.quantity), note: form.note } })
    modalOpen.value = false
    await refresh()
    toast.show('ปรับสต็อกและบันทึกประวัติเรียบร้อย')
  } catch (err: any) { formError.value = err?.data?.statusMessage || 'ปรับสต็อกไม่สำเร็จ' }
  finally { saving.value = false }
}
const movementLabel = (kind: string) => ({ received: 'รับสินค้าเข้า', order: 'ตัดตามคำสั่งซื้อ', adjustment: 'ปรับยอด', return: 'คืนสินค้า' } as Record<string, string>)[kind] || kind
</script>

<template>
  <div class="admin-page-wrap"><div class="admin-page-heading"><div><span class="section-kicker">INVENTORY & STOCK CONTROL</span><h1>คลังสินค้า</h1><p>ติดตามจำนวนคงเหลือ และดูประวัติการเคลื่อนไหวของสินค้า</p></div><button class="button button-primary" @click="openAdjustment()"><AppIcon name="plus" :size="17"/> ปรับสต็อก</button></div>
    <section class="stat-grid compact-stat-grid"><article class="mini-stat-card"><span class="mini-stat-icon mini-purple"><AppIcon name="boxes" :size="18"/></span><span><small>จำนวนสินค้าคงเหลือรวม</small><strong>{{ formatBaht(data?.summary?.units || 0) }} <i>ชิ้น</i></strong></span><span class="mini-stat-end"><AppIcon name="package" :size="15"/></span></article><article class="mini-stat-card"><span class="mini-stat-icon mini-peach"><AppIcon name="alert" :size="18"/></span><span><small>ต้องเติมสต็อก</small><strong>{{ lowCount }} <i>รายการ</i></strong></span><button class="mini-stat-end mini-stat-link" @click="filter = 'low'"><AppIcon name="arrow-up-right" :size="15"/></button></article><article class="mini-stat-card"><span class="mini-stat-icon mini-green"><AppIcon name="circle-check" :size="18"/></span><span><small>สินค้าอยู่ในระดับปกติ</small><strong>{{ Math.max(0, (data?.products?.length || 0) - lowCount) }} <i>รายการ</i></strong></span><span class="mini-stat-end"><AppIcon name="badge-check" :size="15"/></span></article></section>
    <section class="admin-panel stock-overview-panel"><div class="panel-heading stock-panel-heading"><div><span class="section-kicker">STOCK OVERVIEW</span><h2>จำนวนสินค้าตามรายการ</h2></div><div class="stock-filters"><button v-for="item in [{id:'all',label:'ทั้งหมด'}, {id:'low',label:'ใกล้หมด'}, {id:'healthy',label:'ปกติ'}]" :key="item.id" class="filter-tab" :class="{ active: filter === item.id }" @click="filter = item.id">{{ item.label }}<span v-if="item.id === 'low'">{{ lowCount }}</span></button></div></div><div v-if="pending" class="admin-loading-card"><span class="loading-spinner"/> กำลังโหลดสต็อก...</div><div v-else-if="error" class="admin-error-card"><AppIcon name="alert" :size="20"/> โหลดข้อมูลสต็อกไม่สำเร็จ <button class="button button-outline" @click="refresh()">ลองอีกครั้ง</button></div><div v-else-if="visibleProducts.length" class="inventory-list"><div v-for="product in visibleProducts" :key="product.id" class="inventory-row"><div class="inventory-product-image"><ProductArtwork :image-key="product.imageKey" :image-url="product.imageUrl" compact/></div><div class="inventory-product-name"><strong>{{ product.name }}</strong><small>{{ product.sku }} <span>·</span> {{ product.category }}</small></div><div class="inventory-level-wrap"><div class="inventory-level-label"><span>คงเหลือ <strong>{{ product.stock }}</strong> ชิ้น</span><small>จุดแจ้งเตือน {{ product.lowStock }} ชิ้น</small></div><div class="inventory-progress"><i :class="{ 'inventory-progress-low': product.stock <= product.lowStock }" :style="{ width: `${Math.min(100, Math.max(3, product.stock / Math.max(product.lowStock * 3, 15) * 100))}%` }"/></div></div><span class="status-pill" :class="product.stock <= product.lowStock ? 'status-pending' : 'status-delivered'">{{ product.stock === 0 ? 'สินค้าหมด' : product.stock <= product.lowStock ? 'ใกล้หมด' : 'มีสินค้า' }}</span><button class="button button-small button-outline" @click="openAdjustment(product)">ปรับจำนวน</button></div></div><div v-else class="panel-empty"><AppIcon name="boxes" :size="25"/><span>ไม่มีสินค้าที่ตรงกับตัวกรองนี้</span></div><div class="stock-panel-foot"><span><AppIcon name="alert" :size="14"/> จุดแจ้งเตือนปรับได้ในหน้ารายละเอียดสินค้า</span><span>{{ visibleProducts.length }} สินค้า</span></div></section>
    <section class="admin-panel movements-panel"><div class="panel-heading"><div><span class="section-kicker">INVENTORY HISTORY</span><h2>ความเคลื่อนไหวล่าสุด</h2></div><span class="panel-muted-note"><AppIcon name="clock" :size="14"/> อัปเดตล่าสุดก่อน</span></div><div v-if="data?.movements?.length" class="movement-list"><div v-for="movement in data.movements" :key="movement.id" class="movement-row"><span class="movement-icon" :class="`movement-${movement.kind}`"><AppIcon :name="movement.kind === 'order' ? 'bag' : movement.kind === 'received' ? 'package-check' : movement.kind === 'return' ? 'reset' : 'sliders'" :size="17"/></span><span class="movement-info"><strong>{{ movement.productName }}</strong><small>{{ movementLabel(movement.kind) }} <span v-if="movement.reference">· {{ movement.reference }}</span><span v-if="movement.note"> · {{ movement.note }}</span></small></span><span class="movement-delta" :class="{ 'movement-negative': movement.delta < 0 }">{{ movement.delta > 0 ? '+' : '' }}{{ movement.delta }} <small>ชิ้น</small></span><span class="movement-date">{{ formatDate(movement.createdAt, true) }}</span></div></div><div v-else class="panel-empty"><AppIcon name="receipt" :size="22"/><span>ยังไม่มีประวัติการเคลื่อนไหว</span></div></section>
    <AdminModal v-model="modalOpen" title="ปรับจำนวนสต็อก" subtitle="ทุกการปรับยอดจะถูกบันทึกในประวัติคลังสินค้า"><form class="admin-form" @submit.prevent="saveAdjustment"><label class="field-label">เลือกสินค้า <span>*</span><select v-model.number="form.productId" required><option v-for="product in products" :key="product.id" :value="product.id">{{ product.sku }} — {{ product.name }} (คงเหลือ {{ product.stock }})</option></select></label><span class="field-label">ประเภทการปรับ</span><div class="stock-direction-options"><label :class="{ selected: form.direction === 'in' }"><input v-model="form.direction" type="radio" value="in"><span class="stock-direction-plus"><AppIcon name="plus" :size="17"/></span><span><strong>รับสินค้าเข้า</strong><small>เพิ่มจำนวนในคลัง</small></span></label><label :class="{ selected: form.direction === 'out' }"><input v-model="form.direction" type="radio" value="out"><span class="stock-direction-minus"><AppIcon name="minus" :size="17"/></span><span><strong>ปรับลดสต็อก</strong><small>สินค้าชำรุด / ตรวจนับ</small></span></label></div><label class="field-label">จำนวน (ชิ้น) <span>*</span><input v-model.number="form.quantity" type="number" min="1" step="1" required></label><label class="field-label">หมายเหตุ <span>*</span><textarea v-model="form.note" rows="3" required maxlength="400" placeholder="เช่น รับสินค้าจากผู้ผลิต, ตรวจนับประจำเดือน"></textarea></label><p v-if="formError" class="form-error"><AppIcon name="alert" :size="16"/> {{ formError }}</p><div class="modal-actions"><button type="button" class="button button-outline" @click="modalOpen = false">ยกเลิก</button><button type="submit" class="button button-primary" :disabled="saving"><AppIcon :name="saving ? 'loader' : 'save'" :size="16" :class="{ spinning: saving }"/> {{ saving ? 'กำลังบันทึก...' : 'บันทึกการปรับ' }}</button></div></form></AdminModal>
  </div>
</template>
